import { promises as fs } from 'fs';
import path from 'path';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

async function ensureDataFile() {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, '[]\n', 'utf8');
  }
}

async function saveBooks(books) {
  await ensureDataFile();
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2) + '\n', 'utf8');
}

export async function getBooks() {
  await ensureDataFile();
  const raw = await fs.readFile(DATA_FILE, 'utf8');
  try {
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await getBooks();
  const book = {
    id: crypto.randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes?.trim() ?? '',
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function setStatus(id, status) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = status;
  book.finishedAt = status === 'finished' ? new Date().toISOString() : null;
  await saveBooks(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = notes;
  await saveBooks(books);
  return book;
}

