'use server';

import { revalidatePath } from 'next/cache';
import { addBook, setStatus, updateNotes } from '@/lib/books';

export async function addBookAction(formData) {
  const title = formData.get('title')?.toString() ?? '';
  const author = formData.get('author')?.toString() ?? '';
  const notes = formData.get('notes')?.toString() ?? '';

  if (!title.trim() || !author.trim()) return;

  await addBook({ title, author, notes });
  revalidatePath('/');
}

export async function markFinishedAction(formData) {
  const id = formData.get('id')?.toString();
  if (!id) return;
  await setStatus(id, 'finished');
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
}

export async function markReadingAction(formData) {
  const id = formData.get('id')?.toString();
  if (!id) return;
  await setStatus(id, 'reading');
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData) {
  const id = formData.get('id')?.toString();
  const notes = formData.get('notes')?.toString() ?? '';
  if (!id) return;
  await updateNotes(id, notes);
  revalidatePath(`/books/${id}`);
}

