:root {
  color-scheme: light;
  --bg: #fafaf8;
  --text: #1f1f1f;
  --muted: #6b6b6b;
  --border: #e2e0da;
  --accent: #2f5d50;
  --accent-contrast: #ffffff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  line-height: 1.5;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
