import Link from 'next/link';
import { getBooks } from '@/lib/books';
import { addBookAction, markFinishedAction } from './actions';

export const dynamic = 'force-dynamic';

export default async function HomePage() {
  const books = await getBooks();
  const reading = books
    .filter((book) => book.status === 'reading')
    .sort((a, b) => new Date(b.addedAt) - new Date(a.addedAt));
  const finished = books
    .filter((book) => book.status === 'finished')
    .sort((a, b) => new Date(b.finishedAt) - new Date(a.finishedAt));

  return (
    <main>
      <h1>My Books</h1>

      <section>
        <h2>Add a book</h2>
        <form action={addBookAction} className="add-form">
          <input name="title" placeholder="Title" required />
          <input name="author" placeholder="Author" required />
          <textarea name="notes" placeholder="Notes (optional)" rows={2} />
          <button type="submit">Add book</button>
        </form>
      </section>

      <section>
        <h2>Currently reading ({reading.length})</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing here yet.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id} className="book-item">
                <Link href={`/books/${book.id}`}>
                  <strong>{book.title}</strong> <span>by {book.author}</span>
                </Link>
                <form action={markFinishedAction}>
                  <input type="hidden" name="id" value={book.id} />
                  <button type="submit">Mark finished</button>
                </form>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished ({finished.length})</h2>
        {finished.length === 0 ? (
          <p className="empty">Nothing finished yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id} className="book-item">
                <Link href={`/books/${book.id}`}>
                  <strong>{book.title}</strong> <span>by {book.author}</span>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

