import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getBook } from '@/lib/books';
import { markFinishedAction, markReadingAction, updateNotesAction } from '../../actions';
import ShareLink from './ShareLink';

export const dynamic = 'force-dynamic';

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return {};
  return { title: `${book.title} — Book Tracker` };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  const isReading = book.status === 'reading';

  return (
    <main>
      <Link href="/" className="back-link">
        &larr; Back to all books
      </Link>

      <h1>{book.title}</h1>
      <p className="author">by {book.author}</p>
      <p className="status">{isReading ? 'Currently reading' : 'Finished'}</p>

      <form action={isReading ? markFinishedAction : markReadingAction}>
        <input type="hidden" name="id" value={book.id} />
        <button type="submit">{isReading ? 'Mark as finished' : 'Mark as currently reading'}</button>
      </form>

      <section>
        <h2>Notes</h2>
        <form action={updateNotesAction} className="notes-form">
          <input type="hidden" name="id" value={book.id} />
          <textarea name="notes" defaultValue={book.notes} rows={8} placeholder="Your notes on this book..." />
          <button type="submit">Save notes</button>
        </form>
      </section>

      <section>
        <h2>Share this book</h2>
        <ShareLink />
      </section>
    </main>
  );
}

